foreach ($communes as $commune) { $id = str_pad((string)$commune['wilaya_id'], 2, '0', STR_PAD_LEFT); if (isset($locations[$id])) $locations[$id]['communes'][] = ['ar' => $commune['ar_name'], 'fr' => $commune['name']]; }
if (isset($_GET['success'])) { ?><!doctype html><html lang="<?= $lang ?>" dir="<?= $lang === 'ar' ? 'rtl' : 'ltr' ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $lang === 'ar' ? 'تم تأكيد الطلب' : 'Order confirmed' ?> | Lissi</title><link rel="stylesheet" href="style.css"></head><body><main class="success-page"><section class="success-card" role="status"><div class="success-check">✓</div><p class="eyebrow"><?= $lang === 'ar' ? 'تم حفظ طلبك بنجاح' : 'ORDER PLACED SUCCESSFULLY' ?></p><h1><?= $lang === 'ar' ? 'شكراً لطلبك' : 'Thank you for your order' ?></h1><p><?= $lang === 'ar' ? 'سنتصل بك قريباً لتأكيد التفاصيل.' : 'We will call you shortly to confirm the details.' ?></p><strong dir="ltr">#<?= e($_GET['success']) ?></strong><a class="dark success-action" href="index.php?lang=<?= $lang ?>"><?= text('shop') ?></a></section></main></body></html><?php exit; }
