$subtotal = array_reduce($lines, fn($sum, $line) => $sum + $line['price'] * $line['quantity'], 0); $method = $_POST['delivery_method'] ?? ''; $rates = ['Bureau' => 400, 'À domicile' => 700]; $shipping = $rates[$method] ?? null; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); foreach (['full_name','phone','wilaya','commune','delivery_method'] as $field) if (trim($_POST[$field] ?? '') === '') $error = $lang === 'ar' ? 'يرجى ملء جميع الخانات.' : 'Please complete every delivery field.'; if (!valid_phone($_POST['phone'] ?? '')) $error = $lang === 'ar' ? 'رقم الهاتف يجب أن يتكون من 10 أرقام ويبدأ بـ 05 أو 06 أو 07.' : 'Phone must contain exactly 10 digits and start with 05, 06, or 07.'; global $config; $captcha = $_POST['g-recaptcha-response'] ?? ''; if ($config['recaptcha_secret_key'] !== 'YOUR_RECAPTCHA_SECRET_KEY' && !$captcha) $error = 'Please complete the anti-bot check.'; if (!$error && $config['recaptcha_secret_key'] !== 'YOUR_RECAPTCHA_SECRET_KEY') { $response = @file_get_contents('https://www.google.com/recaptcha/api/siteverify?secret=' . urlencode($config['recaptcha_secret_key']) . '&response=' . urlencode($captcha)); if (!$response || !json_decode($response, true)['success']) $error = 'Anti-bot verification failed.'; } if (!$error) { $order = db()->prepare('INSERT INTO orders (full_name,phone,wilaya,commune,delivery_method,shipping_cost,total,status) VALUES (?,?,?,?,?,?,?,?)'); $order->execute([trim($_POST['full_name']),trim($_POST['phone']),trim($_POST['wilaya']),trim($_POST['commune']),$method,$shipping,$subtotal+$shipping,'New']); $orderId = db()->lastInsertId(); $item = db()->prepare('INSERT INTO order_items (order_id,product_id,quantity,unit_price) VALUES (?,?,?,?)'); foreach ($lines as $line) { $item->execute([$orderId,$line['id'],$line['quantity'],$line['price']]); db()->prepare('UPDATE products SET stock=GREATEST(stock-?,0) WHERE id=?')->execute([$line['quantity'],$line['id']]); } $_SESSION['cart']=[]; header('Location: checkout.php?success='.$orderId.'&lang='.$lang); exit; } }
?><!doctype html><html lang="<?= $lang ?>" dir="<?= $lang === 'ar' ? 'rtl' : 'ltr' ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= text('checkout') ?> | Lissi</title><link rel="stylesheet" href="style.css"></head><body><header class="header shell"><a class="brand" href="index.php"><img src="assets/logo.jpeg" alt="Lissi"><span>LISSI</span></a><div class="header-tools"><a href="?lang=ar">ع</a><a href="?lang=fr">FR</a><a href="?lang=en">EN</a><button class="theme-toggle" type="button" data-theme-toggle>Theme</button></div></header><main class="section shell"><p class="eyebrow"><?= text('checkout') ?></p><h2><?= text('details') ?></h2><p class="muted"><?= $lang === 'ar' ? 'اختر طريقة التوصيل لمعرفة السعر.' : 'Choose a delivery method to see the shipping price.' ?></p><?php if ($error): ?><div class="notice"><?= e($error) ?></div><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><label><?= text('name') ?><input name="full_name" required></label><label><?= text('phone') ?><input name="phone" type="tel" inputmode="numeric" pattern="0[567][0-9]{8}" maxlength="10" minlength="10" placeholder="05 00 00 00 00" required></label><div class="form-row"><label><?= text('wilaya') ?><select class="location-select" name="wilaya" id="wilaya" required><option value="">--</option><?php foreach ($locations as $id=>$location): ?><option value="<?= $id ?>"><?= e($lang === 'ar' ? $location['ar'] : $location['fr']) ?></option><?php endforeach; ?></select></label><label><?= text('commune') ?><select class="location-select" name="commune" id="commune" required disabled><option><?= $lang === 'ar' ? 'اختر الولاية أولاً' : 'Choose a Wilaya first' ?></option></select></label></div><label><?= $lang === 'ar' ? 'طريقة التوصيل' : 'Delivery method' ?><select class="location-select" name="delivery_method" id="delivery" required><option value="">-- <?= $lang === 'ar' ? 'اختر الطريقة' : 'Choose method' ?> --</option><option value="À domicile"><?= text('home') ?></option><option value="Bureau"><?= text('bureau') ?></option></select></label><div class="delivery-preview" id="delivery-preview"></div><div class="summary"><div><span>Subtotal</span><b><?= money($subtotal) ?></b></div><div class="total"><span>Total</span><b id="total"><?= money($subtotal) ?></b></div></div><button class="dark" type="submit"><?= $lang === 'ar' ? 'تأكيد الطلب' : ($lang === 'fr' ? 'Confirmer la commande' : 'Confirm order') ?> →</button></form></main><script>const locations=<?= json_encode($locations,JSON_UNESCAPED_UNICODE) ?>,wilaya=document.querySelector('#wilaya'),commune=document.querySelector('#commune'),delivery=document.querySelector('#delivery'),preview=document.querySelector('#delivery-preview'),subtotal=<?= (float)$subtotal ?>;wilaya.addEventListener('change',()=>{const data=locations[wilaya.value];commune.innerHTML='<option value="">--</option>';(data?.communes||[]).forEach(item=>{const o=document.createElement('option');o.value=item.fr;o.textContent='<?= $lang ?>'==='ar'?item.ar:item.fr;commune.appendChild(o)});commune.disabled=!data});delivery.addEventListener('change',()=>{const price=delivery.value==='Bureau'?400:delivery.value==='À domicile'?700:0;preview.textContent=price?'<?= $lang === 'ar' ? 'سعر التوصيل: ' : 'Delivery: ' ?>'+price.toLocaleString('fr-DZ')+' DA':'';document.querySelector('#total').textContent=(subtotal+price).toLocaleString('fr-DZ')+' DA'});</script></body></html>
